//| Forward pass: features[] (length m_n_in) -> predicted P(loss).   |
//| Also refreshes m_hidden[], which TrainStep() reuses so the       |
//| backward pass never has to recompute the forward activations.    |
//+------------------------------------------------------------------+
double
CMlpNet::Forward(
const
double
&features[])
  {
for
(
int
j=
0
; j<m_n_hidden; j++)
     {
double
s=m_b_h[j];
for
(
int
i=
0
; i<m_n_in; i++)
